import{_ as a,a as t,b as i,c as r,d as s,e as n}from"./chunks/ice_3.DdDzg8bL.js";import{_ as o,c as d,o as c,al as l}from"./chunks/framework.CT7RwC5a.js";const S=JSON.parse('{"title":"Airspeed Validation","description":"","frontmatter":{},"headers":[],"relativePath":"ko/advanced_config/airspeed_validation.md","filePath":"ko/advanced_config/airspeed_validation.md"}'),h={name:"ko/advanced_config/airspeed_validation.md"};function p(f,e,_,m,u,g){return c(),d("div",null,e[0]||(e[0]=[l('<h1 id="airspeed-validation" tabindex="-1">Airspeed Validation <a class="header-anchor" href="#airspeed-validation" aria-label="Permalink to &quot;Airspeed Validation&quot;">​</a></h1><p>PX4 includes a set of airspeed validation checks that run continuously during fixed-wing flight to ensure the airspeed data is accurate and reliable.</p><p>If any check fails persistently, the system can declare airspeed as invalid. When this happens, PX4 discards the sensor data and falls back to the option configured by <a href="#aspd_fallback_table">ASPD_FALLBACK</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>By default, the <a href="#missing-data-check">Missing Data</a>, <a href="#data-stuck-check">Data Stuck</a>, and <a href="#innovation-check">Innovation</a> checks are enabled. You can configure which checks are active using the <a href="#aspd_do_checks_table">ASPD_DO_CHECKS</a> parameter.</p></div><h2 id="airspeed-in-px4" tabindex="-1">Airspeed in PX4 <a class="header-anchor" href="#airspeed-in-px4" aria-label="Permalink to &quot;Airspeed in PX4&quot;">​</a></h2><p>PX4 handles multiple types of airspeed:</p><ul><li><p><strong>IAS (Indicated Airspeed):</strong> The raw measurement from the airspeed sensor, directly influenced by sensor characteristics and installation effects (e.g., pitot-static errors).</p></li><li><p><strong>CAS (Calibrated Airspeed):</strong> IAS corrected for sensor-specific and installation-related errors.</p></li><li><p><strong>EAS (Equivalent Airspeed):</strong> <em>Not explicitly handled by PX4</em> - Calibrated airspeed corrected for compressibility effects. While PX4 does not currently model EAS separately, this correction is negligible at low speeds and altitudes, so EAS is treated as equivalent to CAS for simplicity.</p></li><li><p><strong>TAS (True Airspeed):</strong> CAS adjusted for atmospheric effects such as air pressure and temperature (i.e., altitude and atmospheric conditions).</p></li></ul><p>The standard conversion chain used in PX4 is: <code>IAS → CAS (= EAS) → TAS</code>.</p><h2 id="cas-scale-estimation" tabindex="-1">CAS Scale Estimation <a class="header-anchor" href="#cas-scale-estimation" aria-label="Permalink to &quot;CAS Scale Estimation&quot;">​</a></h2><p>PX4 estimates the IAS to CAS scale (referred to as the CAS scale) during flight using GNSS ground speed and wind estimation. To compute the final TAS, standard environment conversions are applied (CAS → TAS).</p><p>This CAS scaling plays an important role in keeping the <a href="#innovation-check">innovation check</a> reliable, since a well-estimated CAS is key to spotting inconsistencies between measured and predicted airspeed. If the estimated CAS scale is inaccurate, it can mask real airspeed faults or trigger false positives.</p><p>If you observe that the CAS scale estimate is consistently off, or if it is converging too slowly, you can manually set it using <a href="#aspd_scale_n_table">ASPD_SCALE_n</a> (where <code>n</code> is the sensor number). <a href="#aspd_scale_apply_table">ASPD_SCALE_APPLY</a> can be used to configure when/if the estimated scale is applied.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For a quick manual CAS scale estimate, compare groundspeed minus windspeed (from the <a href="./../msg_docs/VehicleLocalPosition.html">VehicleLocalPosition</a> and <a href="./../msg_docs/Wind.html">Wind</a> messages, respectively) to indicated airspeed values (in the <a href="./../msg_docs/Airspeed.html">Airspeed</a> message). The ratio of indicated airspeed to groundspeed minus windspeed can provide a reasonable starting estimate for <a href="#aspd_scale_n_table">ASPD_SCALE_n</a>.</p></div><h2 id="validation-checks" tabindex="-1">Validation Checks <a class="header-anchor" href="#validation-checks" aria-label="Permalink to &quot;Validation Checks&quot;">​</a></h2><p>These checks are primarily designed to validate incoming airspeed sensor data and detect potential sensor failures during flight. However, they may also trigger due to configuration issues, estimator inaccuracies, or specific flight conditions that lead to physically inconsistent measurements.</p><p>The following overview summarizes each check, common failure causes, and relevant configuration parameters.</p><h3 id="missing-data-check" tabindex="-1">Missing Data Check <a class="header-anchor" href="#missing-data-check" aria-label="Permalink to &quot;Missing Data Check&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This check is independent of the other validation checks. It must pass for any of the other checks to run.</p></div><p>Triggers when no new airspeed data has been received for more than 1 second.</p><p>Common failure causes:</p><ul><li>Faulty or disconnected sensor.</li></ul><h3 id="data-stuck-check" tabindex="-1">Data Stuck Check <a class="header-anchor" href="#data-stuck-check" aria-label="Permalink to &quot;Data Stuck Check&quot;">​</a></h3><p>Triggers when the measured indicated airspeed (IAS) has not changed for more than 2 seconds.</p><p>Common failure causes:</p><ul><li>Airspeed sensor driver issues.</li><li>Very low sensor resolution.</li></ul><h3 id="innovation-check" tabindex="-1">Innovation Check <a class="header-anchor" href="#innovation-check" aria-label="Permalink to &quot;Innovation Check&quot;">​</a></h3><p>Compares the estimated true airspeed (TAS) to the predicted GNSS-based airspeed (groundspeed minus windspeed). If the difference exceeds a threshold (<a href="#aspd_fs_innov_table">ASPD_FS_INNOV</a>) for a prolonged period (<a href="#aspd_fs_integ_table">ASPD_FS_INTEG</a>), the check fails.</p><p>This check helps detect cases where the measured airspeed is inconsistent with the aircraft&#39;s predicted kinematic state, often indicating sensor drift, (partial) blockage, or sub-optimal sensor placement on the vehicle.</p><p>Common failure causes:</p><ul><li>Faulty or blocked airspeed sensor (<em>sensor fault</em>)</li><li>Poor sensor placement on vehicle (<em>configuration issue</em>)</li><li>Badly estimated CAS scale (or convergence of estimate too slow) (<em>estimator inaccuracy</em>)</li></ul><p>Relevant parameters: <a href="#aspd_fs_innov_table">ASPD_FS_INNOV</a>, <a href="#aspd_fs_integ_table">ASPD_FS_INTEG</a></p><h3 id="load-factor-check" tabindex="-1">Load Factor Check <a class="header-anchor" href="#load-factor-check" aria-label="Permalink to &quot;Load Factor Check&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This check is disabled by default because it often triggers during manual landings, where the vehicle naturally slows down and may momentarily &quot;stall&quot; near touchdown. Since the system cannot reliably distinguish between a real in-flight stall and this expected behaviour, false positives are common.</p></div><p>Checks whether the measured airspeed is physically consistent with the aircraft&#39;s current load factor. If the measured airspeed is too low to plausibly generate the required lift, the sensor reading is considered invalid.</p><p>This check helps detect cases where the airspeed sensor may be under-reading during flight.</p><p>Common failure causes:</p><ul><li>Faulty or blocked airspeed sensor (<em>sensor fault</em>)</li><li>The vehicle is stalling (<em>flight condition</em>)</li><li>Uncalibrated airspeed sensor (<em>configuration issue</em>)</li><li>Poor sensor placement on vehicle (<em>configuration issue</em>)</li><li>Incorrect stall speed configuration (<em>configuration issue</em>)</li></ul><p>Relevant parameters: <a href="#fw_airspd_stall_table">FW_AIRSPD_STALL</a></p><h3 id="first-principle-check" tabindex="-1">First Principle Check <a class="header-anchor" href="#first-principle-check" aria-label="Permalink to &quot;First Principle Check&quot;">​</a></h3><p>Validates whether the measured indicated airspeed (IAS) behaviour matches expected aircraft response based on throttle and pitch inputs.</p><p>Specifically, when throttle is above trim by at least 5% and the aircraft is pitched downward (below <a href="#fw_psp_off_table">FW_PSP_OFF</a>), the rate of change of the IAS should be consistent with the aircraft behaviour.</p><p>If the airspeed readings increase too slowly, this may indicate that the sensor is not responding correctly to dynamic pressure changes — for example, due to pitot tube icing or (partial) blockage.</p><p>Common failure causes:</p><ul><li>Faulty or blocked airspeed sensor (<em>sensor fault</em>)</li><li>Pitot tube icing (<em>sensor fault</em>)</li><li>Excessive drag (e.g. flaps down, landing gear deployed, payload) (<em>flight condition</em>)</li><li>Throttle not producing expected thrust (<em>mechanical issue</em>)</li><li>Incorrect trim or max throttle setting (<em>configuration issue</em>)</li></ul><p>Relevant parameters: <a href="#aspd_fp_t_window_table">ASPD_FP_T_WINDOW</a>, <a href="#fw_psp_off_table">FW_PSP_OFF</a>, <a href="#fw_thr_trim_table">FW_THR_TRIM</a>, <a href="#fw_thr_max_table">FW_THR_MAX</a></p><h2 id="additional-configuration" tabindex="-1">Additional Configuration <a class="header-anchor" href="#additional-configuration" aria-label="Permalink to &quot;Additional Configuration&quot;">​</a></h2><p>To configure the delay before PX4 starts or stops using airspeed sensor data after it passes or fails validation, use:</p><p><a href="#aspd_fs_t_start_table">ASPD_FS_T_START</a>: Delay after passing validation before the sensor is considered valid.</p><p><a href="#aspd_fs_t_stop_table">ASPD_FS_T_STOP</a>: Delay after failing validation before the sensor is considered invalid.</p><h2 id="예" tabindex="-1">예 <a class="header-anchor" href="#예" aria-label="Permalink to &quot;예&quot;">​</a></h2><h3 id="flight-1-blocked-pitot-tube-during-rainy-conditions" tabindex="-1">Flight 1: Blocked Pitot Tube during Rainy Conditions <a class="header-anchor" href="#flight-1-blocked-pitot-tube-during-rainy-conditions" aria-label="Permalink to &quot;Flight 1: Blocked Pitot Tube during Rainy Conditions&quot;">​</a></h3><p>During a fixed-wing flight in rainy conditions, the pitot tube became blocked. The following configuration was used:</p><p><a href="#aspd_do_checks_table">ASPD_DO_CHECKS</a> = 5 (<a href="#missing-data-check">missing data check</a> and <a href="#innovation-check">innovation check</a> enabled) <br><a href="#aspd_fs_innov_table">ASPD_FS_INNOV</a> = 4 <br><a href="#aspd_fs_integ_table">ASPD_FS_INTEG</a> = 10 <br><a href="#fw_airspd_stall_table">FW_AIRSPD_STALL</a> = 12 <br><a href="#aspd_fs_t_stop_table">ASPD_FS_T_STOP</a> = 2</p><p>The figure below shows the incoming airspeed data, and the moment it was flagged invalid (1):</p><p><img src="'+a+'" alt="Example 1: Rain Blockage"></p><p>In this scenario, the airspeed sensor was flagged as invalid by the innovation check. The TAS scale innovation (2) exceeded the threshold specified by <code>ASPD_FS_INNOV</code>. This exceedence is integrated until the <code>ASPD_FS_INTEG</code> threshold is reached (3). This check triggered four seconds after the blockage occurred. This delay consisted of:</p><ul><li>two seconds to accumulate enough error in the innovation integrator (per <code>ASPD_FS_INTEG</code>)</li><li>two seconds to satisfy the <code>ASPD_FS_T_STOP</code> hold time before the failure was declared</li></ul><p><img src="'+t+'" alt="Example 1: Rain Blockage (Innovation Check)"></p><p>Had the <a href="#load-factor-check">load factor check</a> been enabled, the check would have been triggered immediately. The left plot shows that at the time of failure, the vehicle was flying more or less level (load factor 1). When the airspeed suddenly dropped, the check would have triggered (4), as the measured airspeed would not have been enough for the observed flight condition:</p><p><img src="'+i+'" alt="Example 1: Rain Blockage (Load Factor Check)"></p><h3 id="flight-2-pitot-tube-icing" tabindex="-1">Flight 2: Pitot Tube Icing <a class="header-anchor" href="#flight-2-pitot-tube-icing" aria-label="Permalink to &quot;Flight 2: Pitot Tube Icing&quot;">​</a></h3><p>This example involves a vehicle that experienced pitot tube icing during flight. The configuration was:</p><p><a href="#aspd_do_checks_table">ASPD_DO_CHECKS</a> = 23 (<a href="#missing-data-check">missing data check</a>, <a href="#innovation-check">innovation check</a> and <a href="#first-principle-check">first principle check</a> enabled) <br><a href="#fw_psp_off_table">FW_PSP_OFF</a> = 4 (degrees) <br><a href="#fw_thr_trim_table">FW_THR_TRIM</a> = 0.6 <br><a href="#aspd_fp_t_window_table">ASPD_FP_T_WINDOW</a> =2 <br><a href="#aspd_fs_t_stop_table">ASPD_FS_T_STOP</a> = 2</p><p>The figure below shows the incoming airspeed data, and the moment it was flagged invalid (1):</p><p><img src="'+r+'" alt="Example 2: Pitot Tube Icing"></p><p>In this scenario, the airspeed sensor was flagged as invalid by the first principle check. This check requires four consecutive seconds of invalid airspeed:</p><ul><li>two seconds of inconsistent behaviour (as defined by <code>ASPD_FP_T_WINDOW</code>)</li><li>two seconds to satisfy the failure hold time (<code>ASPD_FS_T_STOP</code>)</li></ul><p>The check triggers if the aircraft is nose-down (2), the throttle is 5% above trim (3), but the measured airspeed is not increasing (4) for at least four seconds.</p><p><img src="'+s+'" alt="Example 2: Pitot Tube Icing (First Principle Check)"></p><p>We can check when the innovation check would have triggered. The red line (5) marks the point when the airspeed was flagged as invalid by the first principle check. The green line (6) marks the point when the innovation check would have triggered: more than a minute later. The middle plot shows an increase in the TAS scale estimation after the failure occurred to try and compensate for the difference between the GNSS based speed and the measured airspeed. As a result, the innovation metric stayed within limits for some time. Only when the measured airspeed began decreasing very quickly would the innovation check have failed.</p><p><img src="'+n+'" alt="Example 2: Pitot Tube Icing (Innovation Check)"></p><h2 id="매개변수" tabindex="-1">매개변수 <a class="header-anchor" href="#매개변수" aria-label="Permalink to &quot;매개변수&quot;">​</a></h2><p>Listed below are all the relevant parameters.</p><table tabindex="0"><thead><tr><th>매개변수</th><th>설명</th><th>Used In</th></tr></thead><tbody><tr><td><a id="aspd_do_checks_table"></a><a href="./../advanced_config/parameter_reference.html#ASPD_DO_CHECKS">ASPD_DO_CHECKS</a></td><td>Bitmask to enable/disable individual airspeed validation checks.</td><td></td></tr><tr><td><a id="aspd_fs_innov_table"></a><a href="./../advanced_config/parameter_reference.html#ASPD_FS_INNOV">ASPD_FS_INNOV</a></td><td>Innovation threshold between estimated and predicted TAS.</td><td><a href="#innovation-check">Innovation Check</a></td></tr><tr><td><a id="aspd_fs_integ_table"></a><a href="./../advanced_config/parameter_reference.html#ASPD_FS_INTEG">ASPD_FS_INTEG</a></td><td>Threshold the integral of the innovation must exceed before triggering failure.</td><td><a href="#innovation-check">Innovation Check</a></td></tr><tr><td><a id="fw_airspd_stall_table"></a><a href="./../advanced_config/parameter_reference.html#FW_AIRSPD_STALL">FW_AIRSPD_STALL</a></td><td>Estimated stall speed of vehicle. If misconfigured, the load factor check may trigger.</td><td><a href="#load-factor-check">Load Factor Check</a></td></tr><tr><td><a id="fw_psp_off_table"></a><a href="./../advanced_config/parameter_reference.html#FW_PSP_OFF">FW_PSP_OFF</a></td><td>Pitch at level flight. If misconfigured, the first principle check may trigger.</td><td><a href="#first-principle-check">First Principle Check</a></td></tr><tr><td><a id="fw_thr_trim_table"></a><a href="./../advanced_config/parameter_reference.html#FW_THR_TRIM">FW_THR_TRIM</a></td><td>Throttle trim value. If misconfigured, the first principle check may trigger.</td><td><a href="#first-principle-check">First Principle Check</a></td></tr><tr><td><a id="fw_thr_max_table"></a><a href="./../advanced_config/parameter_reference.html#FW_THR_MAX">FW_THR_MAX</a></td><td>Throttle limit max.</td><td><a href="#first-principle-check">First Principle Check</a></td></tr><tr><td><a id="aspd_fp_t_window_table"></a><a href="./../advanced_config/parameter_reference.html#ASPD_FP_T_WINDOW">ASPD_FP_T_WINDOW</a></td><td>Time window for evaluating airspeed trend in First Principle Check.</td><td><a href="#first-principle-check">First Principle Check</a></td></tr><tr><td><a id="aspd_fs_t_start_table"></a><a href="./../advanced_config/parameter_reference.html#ASPD_FS_T_START">ASPD_FS_T_START</a></td><td>Delay after passing validation before using sensor data. Affects how soon a recovered sensor is trusted.</td><td>All Checks</td></tr><tr><td><a id="aspd_fs_t_stop_table"></a><a href="./../advanced_config/parameter_reference.html#ASPD_FS_T_STOP">ASPD_FS_T_STOP</a></td><td>Delay after failure before declaring data invalid. Affects how quickly faults lead to rejection.</td><td>All Checks</td></tr><tr><td><a id="aspd_fallback_table"></a><a href="./../advanced_config/parameter_reference.html#ASPD_FALLBACK">ASPD_FALLBACK</a></td><td>Fallback mode when airspeed data is lost or invalid.</td><td>System behavior (post-check)</td></tr><tr><td><a id="aspd_scale_apply_table"></a><a href="./../advanced_config/parameter_reference.html#ASPD_SCALE_APPLY">ASPD_SCALE_APPLY</a></td><td>Controls if/when to apply estimated CAS scaling. Poor scaling can cause false innovation failures.</td><td><a href="#innovation-check">Innovation Check</a> (indirect)</td></tr><tr><td><a id="aspd_scale_n_table"></a><a href="./../advanced_config/parameter_reference.html#ASPD_SCALE_1">ASPD_SCALE_n</a></td><td>User-defined IAS to CAS scale override per sensor. May help when auto-scale estimation is unreliable.</td><td><a href="#innovation-check">Innovation Check</a> (indirect)</td></tr></tbody></table>',74)]))}const v=o(h,[["render",p]]);export{S as __pageData,v as default};
